// Coordinates are measured in the unscaled tree world (card: 186 × 174px).
function edgeGeometry(edge){
  const a=edge.a,b=edge.b,ax=(Number(a.x)||0)+93,ay=(Number(a.y)||0)+87,bx=(Number(b.x)||0)+93,by=(Number(b.y)||0)+87;
  const dx=bx-ax,dy=by-ay,vertical=edge.type==='parent'||Math.abs(dy)>Math.abs(dx)*1.35;
  if(edge.type==='parent'){
    const downward=by>ay;
    const x1=ax,y1=ay+(downward?87:-87),x2=bx,y2=by+(downward?-87:87);
    const arc=Math.max(38,Math.abs(y2-y1)*.38)*(downward?1:-1);
    return {path:`M${x1} ${y1} C${x1} ${y1+arc} ${x2} ${y2-arc} ${x2} ${y2}`,midX:(x1+x2)/2,midY:(y1+y2)/2,tagX:(x1+x2)/2,tagY:((y1+y2)/2)-18};
  }
  let x1,y1,x2,y2,control,tagX,tagY;
  if(vertical){
    const direction=dy>0?1:-1;
    x1=ax;y1=ay+87*direction;x2=bx;y2=by-87*direction;
    control=`${x1} ${y1+Math.abs(y2-y1)*.43*direction} ${x2} ${y2-Math.abs(y2-y1)*.43*direction}`;
    tagX=(x1+x2)/2;tagY=(y1+y2)/2-16;
  } else {
    const direction=dx>0?1:-1;
    x1=ax+93*direction;y1=ay;x2=bx-93*direction;y2=by;
    const pull=Math.abs(x2-x1)*.43+30;
    control=`${x1+pull*direction} ${y1} ${x2-pull*direction} ${y2}`;
    tagX=(x1+x2)/2;tagY=(y1+y2)/2-20;
  }
  return {path:`M${x1} ${y1} C${control} ${x2} ${y2}`,midX:(x1+x2)/2,midY:(y1+y2)/2,tagX,tagY};
}
function EdgeGlyph({type}){return ROMANCE.has(type)?(type.startsWith('ex')?<HeartCrack size={12}/>:<Heart size={12}/>):['parent','child','sibling','halfSibling','twin','grandparent','grandchild'].includes(type)?<GitBranch size={12}/>:<ArrowLeftRight size={12}/>}
function edgeTitle(edge){
  if(edge.type==='parent')return `${relationLabel('parent',edge.a)} → ${relationLabel('child',edge.b)}`;
  if(['spouse','partner','fiance','exSpouse','exPartner','sibling','halfSibling','stepSibling','twin'].includes(edge.type))return edge.label;
  return edge.label;
}
function edgeBadgeLabel(edge){
  const map={owner:'Хозяин',parent:'Родитель',spouse:'Супруги',partner:'Пара',fiance:'Помолвка',exSpouse:'Бывшие',exPartner:'Бывшие',sibling:'Родные',halfSibling:'Сводные',stepSibling:'Сводные',twin:'Близнецы',friend:'Друзья',bestFriend:'Лучшие друзья'};
  return map[edge.type]||edge.label;
}
